PRAGMA foreign_keys=OFF;
BEGIN TRANSACTION;
CREATE TABLE IF NOT EXISTS "resultados_premio" ("id" integer NOT NULL PRIMARY KEY AUTOINCREMENT, "monto_premio" decimal NOT NULL, "multiplicador_aplicado" integer NOT NULL, "estado" varchar(20) NOT NULL, "cobrado" bool NOT NULL, "fecha_pago" datetime NULL, "comentario" text NOT NULL, "creado_en" datetime NOT NULL, "metadata" text NOT NULL CHECK ((JSON_VALID("metadata") OR "metadata" IS NULL)), "jugada_id" bigint NOT NULL REFERENCES "jugadas_jugada" ("id") DEFERRABLE INITIALLY DEFERRED, "pagado_por_id" integer NULL REFERENCES "auth_user" ("id") DEFERRABLE INITIALLY DEFERRED);
COMMIT;
